import csv
import io
import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def decision(p):
    return p['action'] in p['allow'] and p['action'] not in p['deny']

def within(p):
    root=posixpath.normpath(p['root']); path=posixpath.normpath(p['path'])
    return path==root or path.startswith(root.rstrip('/')+'/')

def roles(p):
    return sorted(p['definitions'].get(p['assigned'][0],[])) if p['assigned'] else []

